using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;
namespace ROM.EditorTools {
public static partial class RiftBestiaryBuilder {
 public static void Audit(){try{Directory.CreateDirectory("Documentation/bestiary");var lines=new List<string>();foreach(string folder in new[]{"Archmage","Destroyer","DeathKnight","King","Voidheart"}){string path="Assets/SculptiqStudios/InfernalSkeletons/"+folder+"/Prefabs/Infernal"+folder+".prefab";var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);var a=asset.GetComponentInChildren<Animator>();lines.Add(folder+" avatar="+a.avatar+" human="+a.isHuman+" meshRenderers="+string.Join(",",asset.GetComponentsInChildren<MeshRenderer>(true).Select(r=>r.name)));}
foreach(string family in new[]{"Bear_Family/Bear_Male","Boar_Family/Boar_Male","Deers/Deer_red","Fox_Family/Fox_Male","Hare_Family/Hare_Male","Moose_Family/Moose_bull","Wolf_Family/Wolf_Male"}){string root="Assets/Realistic/Forest Animals/"+family;var files=AssetDatabase.FindAssets("t:GameObject",new[]{root+"/prefabs"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>p.EndsWith(".prefab")&&p.ToLowerInvariant().Contains("lowpoly")&&(p.ToLowerInvariant().Contains("_ip")||p.Contains("_C1"))).ToArray();lines.Add("ANIMAL "+family+" PREFABS "+string.Join(",",files));var clips=AssetDatabase.FindAssets("t:Model",new[]{root}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>!p.Contains("RM_")&&!p.Contains("_RM")).SelectMany(p=>AssetDatabase.LoadAllAssetsAtPath(p).OfType<AnimationClip>()).Select(c=>c.name).Distinct().ToArray();lines.Add("CLIPS "+string.Join(",",clips));}File.WriteAllLines("Documentation/bestiary/asset-audit.txt",lines);EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
}